mapper.update:
UPDATE sys82_admin_user_menu
   SET sys82_use_yn = #{useYn}
 WHERE sys82_admin_user_menu_id = #{id}
   AND sys82_user_id = #{userId}

mapper.select:
SELECT m.sys06_menu_id AS menu_id, m.sys06_parent_id AS parent_id, 0 AS depth, m.sys06_menu_nm AS menu_nm,
       m.sys06_seq AS seq, m.sys06_note AS note, a.sys82_admin_user_menu_id AS admin_user_menu_id, a.sys82_use_yn AS use_yn
  FROM sys06_menu m
       LEFT JOIN sys82_admin_user_menu a ON a.sys82_menu_id = m.sys06_menu_id AND a.sys82_user_id = #{userId}
 WHERE m.sys06_menu_id = #{menuId}
